// Package imagetype validates uploaded images and their storage keys.
package imagetype

import (
	"net/http"
	"regexp"

	"github.com/google/uuid"
)

// SniffLen is how many leading bytes Detect needs.
const SniffLen = 512

// extensions maps the allowed MIME types to file extensions. SVG is deliberately not allowed
// because it can carry scripts.
var extensions = map[string]string{
	"image/jpeg": "jpg",
	"image/png":  "png",
	"image/gif":  "gif",
	"image/webp": "webp",
}

// KeyPattern matches keys generated by NewKey, e.g. items/0b6c3d0e-8f3a-4c41-9b7e-1f2a3b4c5d6e.webp.
var KeyPattern = regexp.MustCompile(`^items/[0-9a-f-]{36}\.(jpg|png|webp|gif)$`)

// Detect identifies the image type from the file's leading bytes (not from the client-supplied
// Content-Type). ok is false for anything other than JPEG, PNG, GIF or WebP.
func Detect(head []byte) (mimeType, ext string, ok bool) {
	mimeType = http.DetectContentType(head)
	ext, ok = extensions[mimeType]
	return mimeType, ext, ok
}

// NewKey returns a new random storage key for an image with the given extension.
func NewKey(ext string) string {
	return "items/" + uuid.NewString() + "." + ext
}

// ValidKey reports whether key looks like a key produced by NewKey.
func ValidKey(key string) bool { return KeyPattern.MatchString(key) }
